insert into public.flashcards (id, deck, domain, objective, front, back) values
('f5-051','core',5,'5.1',$$What is a policy exception process?$$,$$A formal, time-bound, documented approval to deviate from policy (with compensating controls and an expiration date) - avoids silent, unmanaged non-compliance.$$),
('f5-052','core',5,'5.1',$$What is NIST CSF (Cybersecurity Framework) at a high level?$$,$$A voluntary framework organizing cybersecurity activities into functions (Identify, Protect, Detect, Respond, Recover) - used to assess and communicate security posture maturity.$$),
('f5-053','core',5,'5.1',$$What is the role of a security steering committee?$$,$$Cross-functional leadership group (IT, legal, business units) that reviews security strategy, approves major policy, and aligns security investment with business risk appetite.$$),
('f5-054','core',5,'5.2',$$How often should a risk register be reviewed, and why?$$,$$Regularly (e.g., quarterly) and after major changes - stale registers miss new risks and keep tracking risks that no longer apply, undermining prioritization.$$),
('f5-055','core',5,'5.2',$$What factors do cyber insurance underwriters typically evaluate?$$,$$MFA coverage, backup practices, patch cadence, incident response plan maturity, and past incident history - poor practices raise premiums or void coverage.$$),
('f5-056','core',5,'5.2',$$How is a qualitative risk heat map constructed?$$,$$Plotting each risk by likelihood (one axis) and impact (other axis) into a grid, often color-coded (green/yellow/red) to visually prioritize response.$$),
('f5-057','core',5,'5.2',$$What is risk transference's limitation?$$,$$Insurance/contracts shift FINANCIAL impact but not reputational damage, operational disruption, or regulatory consequences - transference is partial, not total.$$),
('f5-058','core',5,'5.2',$$What is a single point of failure in risk terms?$$,$$Any component whose failure alone stops a critical function - risk assessments specifically hunt for these because eliminating them yields outsized resilience gains.$$),
('f5-059','core',5,'5.2',$$Inherent risk vs residual risk?$$,$$Inherent: risk with NO controls applied. Residual: risk remaining AFTER controls are applied. The goal of treatment is shrinking inherent risk down to an acceptable residual level.$$),
('f5-060','core',5,'5.3',$$What is vendor lock-in risk?$$,$$Difficulty or cost of switching away from a vendor due to proprietary formats, deep integration, or contractual terms - a risk to weigh during vendor selection, not just after.$$),
('f5-061','core',5,'5.3',$$What is fourth-party risk?$$,$$Risk introduced by your VENDOR's own suppliers/subcontractors, which you have no direct contract with but which can still cause you harm if compromised.$$),
('f5-062','core',5,'5.3',$$What limits an NDA's practical enforceability?$$,$$NDAs deter through legal consequence after a breach, but they don't prevent a breach from happening - and enforcement/damages can be difficult and slow across jurisdictions.$$),
('f5-063','core',5,'5.3',$$What does an SLA penalty clause do?$$,$$Specifies financial credits or remedies owed to the customer if the vendor fails to meet committed service levels - gives the SLA real teeth beyond a paper promise.$$),
('f5-064','core',5,'5.4',$$GDPR's 72-hour rule vs typical US state breach laws?$$,$$GDPR requires notifying the supervisory authority within 72 hours of becoming aware; US state laws typically require notifying AFFECTED INDIVIDUALS within a set window (varies by state) with no single federal standard.$$),
('f5-065','core',5,'5.4',$$What is a Privacy Impact Assessment (PIA)?$$,$$A structured evaluation of how a new project/system collects, uses, and protects personal data, done BEFORE launch to identify and mitigate privacy risks early.$$),
('f5-066','core',5,'5.4',$$Why can non-compliance cascade beyond a single fine?$$,$$Regulatory fines often trigger customer contract breach clauses, loss of certifications required to keep business, and reputational damage compounding the direct financial penalty.$$),
('f5-067','core',5,'5.4',$$What is data localization as a compliance requirement?$$,$$A law requiring certain data to be stored and/or processed within a specific country's borders - stricter than general sovereignty concerns, often industry- or nation-specific.$$),
('f5-068','core',5,'5.5',$$Continuous auditing vs periodic auditing?$$,$$Continuous: automated, ongoing checks against controls (e.g., via Config rules) catching drift immediately. Periodic: scheduled point-in-time reviews (annual audit) - continuous catches issues faster but costs more to build.$$),
('f5-069','core',5,'5.5',$$How does a red team differ from a standard external penetration test?$$,$$Red teams simulate a full adversary campaign (recon, multiple vectors, evasion, persistence) over an extended engagement with broader goals, versus a pen test's typically narrower, time-boxed technical scope.$$),
('f5-070','core',5,'5.6',$$What is gamification in security awareness training?$$,$$Using points, leaderboards, or badges to increase engagement and completion of training - behavioral psychology applied to make compliance training less passive.$$);
insert into public.questions (id, domain, objective, qtype, difficulty, stem, choices, answer, explanation) values
('q5-051',5,'5.1','mcq',2,$q$An engineering team needs to temporarily bypass the password complexity standard for one legacy system that cannot support it, with monitoring added as a compensating control. What should formally document and time-bound this deviation?$q$,$q$["A policy exception process","Silent non-enforcement","Deleting the standard","Ignoring the standard indefinitely"]$q$::jsonb,'0'::jsonb,$q$A formal exception process documents the deviation, its compensating control, and an expiration date - keeping the departure from policy tracked and accountable rather than silent.$q$),
('q5-052',5,'5.1','mcq',2,$q$Which framework organizes cybersecurity activities into the functions Identify, Protect, Detect, Respond, and Recover?$q$,$q$["PCI DSS","NIST Cybersecurity Framework (CSF)","GDPR","SOC 2"]$q$::jsonb,'1'::jsonb,$q$NIST CSF's five core functions structure how organizations assess and communicate cybersecurity maturity. PCI DSS is a payment-card standard, GDPR is privacy law, and SOC 2 is an attestation report.$q$),
('q5-053',5,'5.1','mcq',2,$q$What is the PRIMARY role of a security steering committee?$q$,$q$["Writing application code","Cross-functional review and approval of security strategy, aligning investment with business risk appetite","Running daily vulnerability scans","Managing the help desk queue"]$q$::jsonb,'1'::jsonb,$q$The steering committee brings IT, legal, and business leadership together to set direction and approve major decisions - operational tasks like scanning or code review sit elsewhere.$q$),
('q5-054',5,'5.1','mcq',2,$q$Why is an undocumented, informal exception to policy ("we'll just allow it for now") a governance problem even if the risk is small?$q$,$q$["It creates unmanaged, untracked deviation with no expiration, review, or compensating control - exactly what a formal exception process prevents","Small risks never matter","Informal exceptions are always safer than formal ones","Governance only concerns large risks"]$q$::jsonb,'0'::jsonb,$q$Informal exceptions accumulate invisibly and never expire or get reviewed - the formal process exists precisely to keep every deviation tracked and time-bound, regardless of its size.$q$),
('q5-055',5,'5.1','matching',2,$q$Match each governance document/body to its role.$q$,$q${"left":["Policy","Steering committee","Exception process","Standard"],"right":["High-level mandatory intent","Cross-functional oversight and approval","Formal, time-bound deviation with compensating controls","Mandatory specific requirement"]}$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Policy sets intent; the steering committee provides oversight; exceptions formally document deviations; standards specify mandatory concrete requirements - each plays a distinct governance role.$q$),
('q5-056',5,'5.2','mcq',2,$q$A risk register hasn't been reviewed in three years despite two major system migrations. What is the MOST likely consequence?$q$,$q$["The register is still perfectly accurate","New risks from the migrations are missing and stale risks may no longer be relevant, undermining prioritization","Risk registers never need review","This has no operational impact"]$q$::jsonb,'1'::jsonb,$q$Without regular review, the register drifts out of sync with reality - missing genuinely new risks while still tracking resources against risks that may no longer exist.$q$),
('q5-057',5,'5.2','mcq',2,$q$A cyber insurance underwriter denies a claim after a ransomware incident, citing the company's failure to maintain MFA as represented in the application. What does this illustrate?$q$,$q$["Insurance always pays regardless of security practices","Underwriters evaluate security practices, and misrepresenting them can void coverage when a claim is filed","MFA is unrelated to cyber insurance","Insurance eliminates all need for security controls"]$q$::jsonb,'1'::jsonb,$q$Insurers underwrite based on represented security practices; failing to actually maintain what was represented (like MFA) is grounds for denying a claim - insurance is not a substitute for the controls themselves.$q$),
('q5-058',5,'5.2','mcq',2,$q$On a qualitative risk heat map, which risk would sit in the most urgent (upper-right, red) zone?$q$,$q$["Low likelihood, low impact","High likelihood, high impact","Low likelihood, high impact only","Impact and likelihood are not plotted together"]$q$::jsonb,'1'::jsonb,$q$Heat maps plot likelihood against impact; the combination of both being high lands in the most urgent zone, prioritizing it for immediate treatment.$q$),
('q5-059',5,'5.2','mcq',2,$q$A company transfers financial risk via cyber insurance after a breach, but still suffers significant customer churn and negative press. What does this illustrate about risk transference?$q$,$q$["Transference eliminates all forms of risk","Transference shifts FINANCIAL impact but not reputational or operational consequences - it's partial, not total","Transference is always a complete solution","Insurance prevents reputational damage automatically"]$q$::jsonb,'1'::jsonb,$q$Insurance and contracts move the monetary burden to a third party, but reputational and operational fallout from a breach remain the organization's to bear regardless.$q$),
('q5-060',5,'5.2','mcq',2,$q$A payment system depends on a single unclustered database server with no failover. Risk assessors flag this specifically as what?$q$,$q$["A compensating control","A single point of failure","A qualitative risk","An accepted risk automatically"]$q$::jsonb,'1'::jsonb,$q$A single component whose failure alone halts a critical function is a single point of failure - a specific, high-value target for risk assessors because eliminating it yields outsized resilience.$q$),
('q5-061',5,'5.2','mcq',3,$q$Before any controls are applied, a new cloud service carries significant exposure. After encryption, access controls, and monitoring are implemented, meaningfully less risk remains. What are these two risk states called, respectively?$q$,$q$["Residual risk; inherent risk","Inherent risk; residual risk","Accepted risk; transferred risk","Qualitative risk; quantitative risk"]$q$::jsonb,'1'::jsonb,$q$Inherent risk exists with no controls applied; residual risk is what remains after controls - treatment aims to shrink inherent risk down to an acceptable residual level.$q$),
('q5-062',5,'5.2','mcq',2,$q$Which risk treatment strategy is illustrated when a company declines to enter a new market specifically because the associated cyber risk is unacceptable?$q$,$q$["Mitigation","Avoidance","Transference","Acceptance"]$q$::jsonb,'1'::jsonb,$q$Choosing not to undertake the risky activity at all is avoidance - eliminating the risk source rather than reducing, shifting, or bearing it.$q$),
('q5-063',5,'5.2','mcq',2,$q$A CISO reports that residual risk on a critical system remains above the board's stated risk tolerance even after all planned controls. What should happen next?$q$,$q$["Ignore the gap silently","Escalate to leadership for a decision: invest in further mitigation, accept formally, or reconsider the activity","Automatically shut down the system with no discussion","Delete the risk register entry"]$q$::jsonb,'1'::jsonb,$q$When residual risk exceeds tolerance, the decision belongs to leadership - they can fund further mitigation, formally accept the gap, or reconsider the activity, but silence or unilateral action bypasses proper governance.$q$),
('q5-064',5,'5.2','ordering',2,$q$Order the quantitative risk workflow from first calculation to final decision input.$q$,$q$["Determine asset value and exposure factor to calculate SLE","Estimate ARO from historical/threat data","Calculate ALE (SLE x ARO)","Compare ALE to control cost to justify (or reject) the investment"]$q$::jsonb,$q$[0,1,2,3]$q$::jsonb,$q$Asset value and exposure factor produce the SLE (loss per event); estimating frequency (ARO) allows calculating ALE (expected annual loss); comparing ALE to control cost is the final financial justification step.$q$),
('q5-065',5,'5.3','mcq',2,$q$A company selects a cloud vendor whose proprietary data format makes migrating to a competitor prohibitively expensive years later. What risk did they underweight during selection?$q$,$q$["Vendor lock-in risk","Data sovereignty","Right-to-audit","Fourth-party risk"]$q$::jsonb,'0'::jsonb,$q$Difficulty and cost of switching away from a vendor due to proprietary formats or deep integration is vendor lock-in risk - worth weighing during selection, not discovered painfully afterward.$q$),
('q5-066',5,'5.3','mcq',2,$q$A breach originates not from your direct vendor, but from a subcontractor that vendor uses for cloud hosting, with whom you have no contract. What is this called?$q$,$q$["First-party risk","Fourth-party risk","Internal risk","Compliance risk"]$q$::jsonb,'1'::jsonb,$q$Risk introduced by your vendor's own suppliers - beyond your direct contractual relationship - is fourth-party risk, and it can still reach and harm your organization.$q$),
('q5-067',5,'5.3','mcq',2,$q$A vendor breaches confidentiality and the affected company sues under the signed NDA. What does this scenario illustrate about NDAs?$q$,$q$["NDAs prevent breaches from ever happening","NDAs provide legal recourse AFTER a breach but don't prevent the breach itself","NDAs are unenforceable in all cases","NDAs replace the need for technical controls"]$q$::jsonb,'1'::jsonb,$q$An NDA deters and provides legal remedy after a violation - it's a legal instrument, not a technical control that stops the breach from occurring in the first place.$q$),
('q5-068',5,'5.3','mcq',2,$q$A vendor misses its committed 99.9% uptime SLA for three consecutive months. What contractual mechanism should compensate the customer?$q$,$q$["An SLA penalty/service-credit clause","A right-to-audit clause","An NDA","A BPA"]$q$::jsonb,'0'::jsonb,$q$SLA penalty clauses specify financial credits or remedies owed when committed service levels aren't met - giving the SLA real consequences beyond a paper promise.$q$),
('q5-069',5,'5.3','mcq',3,$q$Why should supply chain risk analysis extend to fourth parties, not just direct vendors?$q$,$q$["Fourth parties never pose real risk","Risk flows transitively - a breach several tiers down the supply chain can still reach your organization through the vendor relationship","Fourth-party risk is always the vendor's sole responsibility with zero impact to you","Regulations never consider fourth parties"]$q$::jsonb,'1'::jsonb,$q$A compromise at your vendor's own supplier can still cascade into your organization's data or operations - transitive risk doesn't stop at the first contractual boundary.$q$),
('q5-070',5,'5.3','mcq',2,$q$Which vendor assessment method provides the STRONGEST independent assurance before signing a contract?$q$,$q$["The vendor's own marketing claims","An independent third-party audit report (e.g., SOC 2) reviewed during due diligence","A handshake agreement","Skipping assessment to save time"]$q$::jsonb,'1'::jsonb,$q$An independent audit report carries objectivity that marketing claims or informal agreements cannot - it's the strongest pre-contract assurance short of running your own assessment.$q$),
('q5-071',5,'5.4','mcq',2,$q$A US company with EU customers suffers a breach. Which timeline governs their notification obligation to EU regulators specifically?$q$,$q$["GDPR's 72-hour notification requirement to the supervisory authority","No timeline applies to EU customers","A 1-year grace period","Notification is entirely optional"]$q$::jsonb,'0'::jsonb,$q$GDPR applies to organizations processing EU residents' data regardless of where the company is based, requiring notification to the supervisory authority within 72 hours of becoming aware.$q$),
('q5-072',5,'5.4','mcq',2,$q$Why is there no single unified US breach notification timeline, unlike GDPR's 72-hour rule?$q$,$q$["The US has one single federal law identical to GDPR","US breach notification is governed by a patchwork of individual state laws with varying timelines and requirements","The US has no breach notification laws at all","All US states use exactly 72 hours"]$q$::jsonb,'1'::jsonb,$q$Absent a comprehensive federal privacy law, US breach notification obligations come from individual state statutes, each with its own timeline and triggering criteria - a genuine compliance complexity.$q$),
('q5-073',5,'5.4','mcq',2,$q$Before launching a new app that collects location data from children, the company conducts a structured review of data collection, use, and protection to catch privacy risks early. What is this called?$q$,$q$["A Privacy Impact Assessment (PIA)","A penetration test","A SOC 2 audit","A risk register"]$q$::jsonb,'0'::jsonb,$q$A PIA proactively evaluates a project's data practices before launch, specifically to catch and mitigate privacy risks early - distinct from a security-focused pen test or audit.$q$),
('q5-074',5,'5.4','mcq',3,$q$A company fails a PCI DSS audit and, beyond the direct fine, loses its ability to process card payments and faces contract termination from a major retail partner. What does this illustrate?$q$,$q$["Fines are always the only consequence of non-compliance","Non-compliance consequences can cascade beyond the direct fine into lost certifications and contractual/business impact","PCI DSS has no real consequences","Only technical teams are affected by compliance failures"]$q$::jsonb,'1'::jsonb,$q$Real non-compliance impact often extends well past the monetary fine into lost operating capability and business relationships - a much larger business consequence than the fine alone suggests.$q$),
('q5-075',5,'5.4','mcq',2,$q$A law requires that a country's citizens' health records be stored and processed only on servers physically located within that country. What specific requirement is this?$q$,$q$["Data masking","Data localization","Key escrow","Attestation"]$q$::jsonb,'1'::jsonb,$q$Data localization is a specific legal requirement to keep certain data within a country's borders - stricter and more concrete than the general concept of data sovereignty.$q$),
('q5-076',5,'5.4','mcq',2,$q$How does data localization differ from the broader concept of data sovereignty?$q$,$q$["They are unrelated concepts","Localization is a specific legal REQUIREMENT to keep data within a country's borders; sovereignty is the broader principle that data is subject to the laws of wherever it resides","Localization only applies to government data","Sovereignty is always stricter than localization"]$q$::jsonb,'1'::jsonb,$q$Sovereignty is the general principle that data is governed by the laws of its physical location; localization is a specific, often stricter legal mandate requiring that data stay within particular borders.$q$),
('q5-077',5,'5.4','mcq',2,$q$Which document, signed annually by employees, provides documented evidence that they were made aware of company security policy?$q$,$q$["Attestation by an external auditor","Policy acknowledgement","A SOC 2 report","A risk register entry"]$q$::jsonb,'1'::jsonb,$q$Employee sign-off confirming they've read policy is a policy acknowledgement - distinct from formal attestation, which is typically management or auditor certification that controls are met.$q$),
('q5-078',5,'5.4','mcq',2,$q$Which best distinguishes an external compliance audit from an internal self-assessment for regulatory purposes?$q$,$q$["They provide identical assurance","An external audit provides independent, typically regulator/customer-trusted assurance; a self-assessment is useful internal preparation but weaker assurance","Self-assessments are always preferred by regulators","External audits are never required by regulation"]$q$::jsonb,'1'::jsonb,$q$Independence gives external audits credibility that self-assessments, however useful for internal preparation, cannot match - many regulations explicitly require the external form.$q$),
('q5-079',5,'5.5','mcq',2,$q$Which approach uses automated, continuous checks (e.g., cloud config rules) to catch control drift in near real time rather than waiting for a scheduled review?$q$,$q$["Continuous auditing","Periodic auditing only","Self-assessment only","No auditing at all"]$q$::jsonb,'0'::jsonb,$q$Continuous auditing runs automated, ongoing checks against controls, catching drift far faster than a scheduled point-in-time audit would.$q$),
('q5-080',5,'5.5','mcq',2,$q$What is the main trade-off of continuous auditing versus a traditional annual audit?$q$,$q$["Continuous auditing catches issues faster but costs more to build and maintain than a point-in-time review","Continuous auditing is always cheaper and slower","Annual audits catch issues faster","There is no trade-off"]$q$::jsonb,'0'::jsonb,$q$Continuous auditing trades higher upfront and ongoing tooling investment for much faster detection of drift compared to a once-a-year snapshot review.$q$),
('q5-081',5,'5.5','mcq',2,$q$How does a red team engagement typically differ in scope from a standard external penetration test?$q$,$q$["A red team simulates a full adversary campaign over an extended period with broader goals (recon, multiple vectors, persistence); a pen test is typically narrower and time-boxed","They are identical in every respect","Red teams never use social engineering","Pen tests always run longer than red team engagements"]$q$::jsonb,'0'::jsonb,$q$Red teaming mimics a real adversary campaign across a longer engagement and broader objective set, while a standard pen test typically has a narrower, time-boxed technical scope.$q$),
('q5-082',5,'5.5','mcq',2,$q$An organization defines exactly which systems, IP ranges, and techniques are in scope before authorizing a pen test. What document captures this?$q$,$q$["Rules of engagement","A risk register","An SLA","A BIA"]$q$::jsonb,'0'::jsonb,$q$Rules of engagement define scope, permitted techniques, timing, and authorization before testing begins - without it, testing is legally and operationally indistinguishable from an attack.$q$),
('q5-083',5,'5.5','mcq',2,$q$Why might a regulated financial institution require BOTH an internal audit team AND periodic external audits?$q$,$q$["Internal audits provide ongoing self-monitoring; external audits provide independent, regulator-trusted assurance neither alone fully satisfies","Only one type of audit is ever legally sufficient","External audits replace the need for internal controls entirely","Internal audits are never useful"]$q$::jsonb,'0'::jsonb,$q$Internal audit gives continuous self-monitoring capability; external audit provides the independent assurance regulators and customers require - together they cover what neither fully provides alone.$q$),
('q5-084',5,'5.5','mcq',3,$q$A purple team exercise pairs red team attackers with blue team defenders in real time, sharing findings as they occur. What is the primary benefit over running red and blue exercises separately?$q$,$q$["It eliminates the need for any defenders","Immediate knowledge transfer improves detection and response capability faster than a delayed after-action report would","It is always cheaper than separate exercises","Purple teaming replaces the need for a SOC"]$q$::jsonb,'1'::jsonb,$q$Real-time collaboration between attackers and defenders accelerates learning - the blue team improves detection immediately rather than waiting for a post-engagement report weeks later.$q$),
('q5-085',5,'5.6','mcq',2,$q$A security awareness program adds a leaderboard and badges for completing modules and reporting phishing simulations. What technique is this?$q$,$q$["Gamification","Attestation","Threat modeling","Chain of custody"]$q$::jsonb,'0'::jsonb,$q$Using points, leaderboards, or badges to boost engagement with training is gamification - applying behavioral incentives to otherwise passive compliance activities.$q$),
('q5-086',5,'5.6','mcq',2,$q$Why might gamification improve security awareness outcomes compared to mandatory click-through training alone?$q$,$q$["It has no measurable effect","Behavioral incentives (competition, recognition) increase engagement and completion compared to passive, obligatory training","Gamification eliminates the need for any training content","It only works for technical staff"]$q$::jsonb,'1'::jsonb,$q$Adding recognition and competition taps into intrinsic motivation, typically driving higher engagement than training people complete only because it's mandatory.$q$),
('q5-087',5,'5.6','mcq',2,$q$Which metric BEST demonstrates that an awareness program is changing actual behavior, not just completion rates?$q$,$q$["Number of training modules purchased","Trending phishing simulation click/report rates over time","Number of PowerPoint slides in the training","Budget spent on the program"]$q$::jsonb,'1'::jsonb,$q$Behavioral outcome metrics - falling click rates and rising report rates over time - prove the program changes real behavior, unlike input metrics like spend or content volume.$q$),
('q5-088',5,'5.6','mcq',2,$q$Board members receive a quarterly one-page summary of phishing trends, incident counts, and program maturity instead of raw technical logs. Why is this framing appropriate?$q$,$q$["Boards need business-risk-level summaries to make governance decisions, not operational technical detail","Boards should receive identical detail to SOC analysts","Executive summaries have no legitimate purpose","Raw logs are always the better format for any audience"]$q$::jsonb,'0'::jsonb,$q$Board-level reporting should translate technical activity into business risk and trend terms the board can act on for governance and investment decisions - raw logs serve a different, operational audience.$q$),
('q5-089',5,'5.6','mcq',2,$q$An employee reports a suspicious email that turns out to be a false alarm. What should the security team's response be to encourage a strong reporting culture?$q$,$q$["Publicly criticize the employee for wasting time","Thank them for reporting and reinforce that false alarms are a normal, welcome part of a healthy reporting culture","Ignore the report entirely","Revoke their email access as a precaution"]$q$::jsonb,'1'::jsonb,$q$Punishing false alarms teaches people to stop reporting, including real threats later. Positive reinforcement for reporting - even when wrong - keeps the detection channel open and trusted.$q$),
('q5-090',5,'5.6','mcq',2,$q$Which awareness topic MOST directly reduces the risk of business email compromise style attacks?$q$,$q$["Printer maintenance procedures","Training staff to verify unusual payment/wire requests through a separate, trusted channel before acting","Password length requirements alone","Office seating charts"]$q$::jsonb,'1'::jsonb,$q$BEC relies on urgency and impersonation over a single channel (email); training staff to verify unusual financial requests out-of-band directly closes that gap.$q$);
